-- 알코올감(alcohol_presence)은 더 이상 카탈로그의 숫자 칸이 아니다.
-- Only 424 of 59,239 bottles ever had a read value (a tasting note's "warming"
-- turned into a number); the heat a drink leaves is its strength, which
-- abv_percent already states for nearly every bottle. Since 2026-10-25 the card
-- reads alcohol presence from the ABV placed on the kind's five bands
-- (catalog/sensory/abv-bands.json), so the column goes, together with every
-- stored fact, relation and source word that named it and the validators that
-- listed it. The sensation itself (the reader's "열감" answers, the warmth
-- explanations) stays in the card engine, fed by the ABV.

-- 1. Stored data that named the axis. The working copy was cleaned first, so
--    these normally touch little; they make the migration safe on its own.
--    Only the structured columns change, so the source-change trigger does
--    not fire.
update public.alcohol_tasting_profiles
  set level_sources = level_sources - 'alcohol_presence'
  where level_sources ? 'alcohol_presence';

update public.alcohol_tasting_profiles
  set structured_sensory = jsonb_set(structured_sensory, '{facts}', coalesce(
    (select jsonb_agg(f) from jsonb_array_elements(structured_sensory->'facts') f where not (f#>>'{target,kind}' = 'axis' and f#>>'{target,key}' = 'alcohol_presence')), '[]'::jsonb))
  where structured_sensory is not null
    and exists (select 1 from jsonb_array_elements(structured_sensory->'facts') f where f#>>'{target,kind}' = 'axis' and f#>>'{target,key}' = 'alcohol_presence');

update public.alcohol_tasting_profiles
  set structured_semantics = jsonb_set(structured_semantics, '{entries}', coalesce(
    (select jsonb_agg(e) from jsonb_array_elements(structured_semantics->'entries') e where not (e#>>'{identity,target,kind}' = 'axis' and e#>>'{identity,target,key}' = 'alcohol_presence') and not (e#>>'{identity,from,kind}' = 'axis' and e#>>'{identity,from,key}' = 'alcohol_presence') and not (e#>>'{identity,to,kind}' = 'axis' and e#>>'{identity,to,key}' = 'alcohol_presence')), '[]'::jsonb))
  where structured_semantics is not null
    and exists (select 1 from jsonb_array_elements(structured_semantics->'entries') e where (e#>>'{identity,target,kind}' = 'axis' and e#>>'{identity,target,key}' = 'alcohol_presence') or (e#>>'{identity,from,kind}' = 'axis' and e#>>'{identity,from,key}' = 'alcohol_presence') or (e#>>'{identity,to,kind}' = 'axis' and e#>>'{identity,to,key}' = 'alcohol_presence'));

-- 2. Validators and helpers that listed the axis, rebuilt from the live
--    definitions without it.
